
function createAbortError(signal) {
  const error = new Error("The retry operation was aborted.");
  error.name = "AbortError";
  error.cause = signal?.reason;
  return error;
}

function calculateDelay(attempt, options) {
  const { delay, backoff, factor, maxDelay, jitter } = options;

  let waitTime = delay;

  if (backoff === "linear") {
    waitTime = delay * attempt;
  } else if (backoff === "exponential") {
    waitTime = delay * factor ** (attempt - 1);
  }

  waitTime = Math.min(waitTime, maxDelay);

  if (jitter) {
    waitTime = Math.random() * waitTime;
  }

  return Math.floor(waitTime);
}

function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(createAbortError(signal));
      return;
    }

    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", abort);
      resolve();
    }, ms);

    function abort() {
      clearTimeout(timer);
      signal.removeEventListener("abort", abort);
      reject(createAbortError(signal));
    }

    signal?.addEventListener("abort", abort, { once: true });
  });
}

export async function retry(operation, options = {}) {
  if (typeof operation !== "function") {
    throw new TypeError("Operation must be a function.");
  }

  const config = {
    retries: 3,
    delay: 1000,
    backoff: "exponential",
    factor: 2,
    maxDelay: Infinity,
    jitter: false,
    shouldRetry: () => true,
    onRetry: () => {},
    ...options
  };

  const {
    retries,
    delay,
    backoff,
    factor,
    maxDelay,
    jitter,
    shouldRetry,
    onRetry,
    signal
  } = config;

  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError("Retries must be a non-negative integer.");
  }

  if (!Number.isFinite(delay) || delay < 0) {
    throw new TypeError("Delay must be a non-negative number.");
  }

  if (!["fixed", "linear", "exponential"].includes(backoff)) {
    throw new TypeError("Invalid backoff strategy.");
  }

  if (!Number.isFinite(factor) || factor < 1) {
    throw new TypeError("Factor must be a number greater than or equal to 1.");
  }

  if (maxDelay < 0 || Number.isNaN(maxDelay)) {
    throw new TypeError("maxDelay must be non-negative.");
  }

  if (typeof jitter !== "boolean") {
    throw new TypeError("Jitter must be a boolean.");
  }

  if (typeof shouldRetry !== "function") {
    throw new TypeError("shouldRetry must be a function.");
  }

  if (typeof onRetry !== "function") {
    throw new TypeError("onRetry must be a function.");
  }

  for (let attempt = 1; ; attempt++) {
    if (signal?.aborted) {
      throw createAbortError(signal);
    }

    try {
      return await operation({ attempt, signal });
    } catch (error) {
      if (signal?.aborted) {
        throw createAbortError(signal);
      }

      if (attempt > retries || !(await shouldRetry(error, attempt))) {
        throw error;
      }

      const nextDelay = calculateDelay(attempt, config);

      await onRetry(error, attempt, nextDelay);

      await sleep(nextDelay, signal);
    }
  }
}

export default retry;
